import type { Game, MediaFile } from "./types";

const u = (id: string, w = 1200) =>
  `https://images.unsplash.com/photo-${id}?auto=format&fit=crop&w=${w}&q=80`;

const t = (daysAgo: number) =>
  new Date(Date.UTC(2026, 7, 22) - daysAgo * 86_400_000).toISOString();

/** Screenshots uploaded by scripts/upload-screens.ts → game-images/screens/<slug>/NN.jpg */
const s = (slug: string, n: number) =>
  `https://gkkumcbfubvrouovbbcf.supabase.co/storage/v1/object/public/game-images/screens/${slug}/${String(n).padStart(2, "0")}.jpg`;

/** A YouTube clip entry (the player honours `t=` start offsets). */
const yt = (
  gameId: string,
  videoId: string,
  startSeconds: number,
  title: string,
  caption?: string,
): MediaFile => ({
  id: `${gameId}-yt${startSeconds}`,
  game_id: gameId,
  kind: "video",
  url: `https://www.youtube.com/watch?v=${videoId}&t=${startSeconds}s`,
  title,
  caption: caption ?? null,
  created_at: t(0),
});

/** Teibl Taimi full-season videos on the ИМПРОКОМ channel. */
const TT_S1 = "om6nokYjYFw";
const TT_S2 = "oK8paUMVhgM";
const TT_S3 = "LWGIRs5P26U";
const TT_S4 = "TAAYHwq33I4";
const TT_S5 = "7MZZWt25HUY";

/** Gallery entries for a game's uploaded screenshots — one per caption (null = no caption). */
const shots = (
  gameId: string,
  slug: string,
  captions: (string | null)[],
): MediaFile[] =>
  captions.map((caption, i) => ({
    id: `${gameId}-m${i + 1}`,
    game_id: gameId,
    kind: "image",
    url: s(slug, i + 1),
    caption,
    mime_type: "image/jpeg",
    created_at: t(0),
  }));

