    rules_md: `## მიზანი
დაწერე რიცხვი, რომელიც არცერთ სხვა მოთამაშეს არ დაემთხვევა — და ქულა აიღე.

## როგორ ვითამაშოთ
1. მოთამაშეთა რაოდენობა განსაზღვრავს დიაპაზონს: თუ ხართ **N** მოთამაშე, თითოეულმა უნდა აირჩიოს რიცხვი **1-დან N-მდე**.
2. ყველას აქვს **3 წუთი**, რომ ფურცელზე ფარულად ჩაწეროს არჩეული რიცხვი — სხვებს არ უნდა დაანახოს.
3. დროის ამოწურვისას ყველა ერთდროულად აჩვენებს თავის ფურცელს.

## ქულები
- ვინც **უნიკალურ** რიცხვს დაწერს (არავის არ დაემთხვევა) — იღებს **2 ქულას**.
- ვისი რიცხვიც ერთხელ მაინც დაემთხვა სხვას — იღებს **0 ქულას**.

## რჩევა
რაც უფრო მეტი მოთამაშეა, მით უფრო რთულდება ყველასთვის უნიკალური რიცხვის პოვნა — იფიქრე, რომელ რიცხვს აირჩევს ყველაზე ნაკლები ადამიანი.

## ვარიანტი
ითამაშეთ რამდენიმე რაუნდი და აწარმოეთ საერთო ანგარიში.`,
