    rules_md: `## მიზანი
იაპონური ბალანსის თამაში Tumi-ishi — „ქვების მთა“: **არასწორი ფორმის ხის „ქვები“** ერთმანეთზე უნდა დააწყო. ვისზეც კოშკი დაინგრა — სიცოცხლეს კარგავს. ბოლომდე „ცოცხლად“ დარჩენილი იმარჯვებს.

## მოსამზადებელი
1. **Tumi-ishi-ს ნაკრები** — 10–15 არასწორი ფორმის ხის ქვა. ალტერნატივა: **მართლა გლუვი კენჭები** მდინარიდან, სხვადასხვა ზომის.
2. **მყარი, არამოძრავი მაგიდა** — მაგიდის რყევა კოშკს ანგრევს.
3. დაფა **სიცოცხლეებისთვის** — ყველას 3 „გული“.

## როგორ ვითამაშოთ
1. სვლაზე მოთამაშე **ნებისმიერ ქვას** იღებს და ჯერ **კამათელივით აგდებს მაგიდაზე**: რომელ წახნაგზეც დაეცა, **იმ წახნაგით** უნდა დადოს კოშკის თავზე.
2. ქვა იდება **ერთი ხელით**; კოშკის ხელით დაჭერა ან გასწორება **აკრძალულია**. ქვის დადების შემდეგ ხელი უნდა მოაშორო — კოშკი 3 წამი უნდა იდგეს.
3. **ვისზეც კოშკი დაინგრა** — სიცოცხლეს კარგავს, კოშკი კი ხელახლა იწყება ნულიდან.
4. **გამძაფრება:** როცა ერთი მოთამაშე ამოვარდება, დანარჩენები დანგრევაზე უკვე **ორ** სიცოცხლეს კარგავენ; როცა მეორეც ამოვარდება — **სამს**. ფინალი ერთი შეცდომით წყდება.
5. ბოლომდე ცოცხლად დარჩენილი — გამარჯვებულია.

## ვარიანტები
- **არჩევანით:** აგდების გარეშე — ქვას ისე დებ, როგორც გინდა, მაგრამ **ორი ხელით არა**.
- **ბრმა:** ყოველი მესამე სვლა თვალდახუჭული.
- **სიმაღლეზე:** ვინ ააშენებს **ყველაზე მაღალ** კოშკს 2 წუთში — მარტო.
- **გუნდური კოშკი:** ყველა ერთ კოშკზე, სიცოცხლეები საერთოა — რამდენი ქვა დაიდება, სანამ დაინგრევა? რეკორდი დაფაზე.

## რჩევა
**ბრტყელი წახნაგი** ბედია, არა უნარი — მაგრამ **სად** დადებ, უნარია: კოშკის სიმძიმის ცენტრზე, არა კიდეზე. სუნთქვა შეიკავე. კამერა ახლოს — თითების კანკალი ჩანს.`,
