    rules_md: `## მიზანი
კამათლებზე დაფუძნებული „პოკერი კამათლებით“ — კლასიკური Yahtzee-ს ტიპის თამაში, სადაც გუნდი **ერთად** აგროვებს კომბინაციებს და ავსებს ქულების ცხრილს. სტრატეგია ისაა, რომ იშვიათი კომბინაციები ჯერ დააგროვო, ადვილი კი ბოლოსთვის შეინახო.

## როგორ ვითამაშოთ
1. თითოეულ სვლაზე ეძლევათ **3 გდება**: პირველი გდების შემდეგ აქტიური მოთამაშე ირჩევს, რომელი კამათელი დატოვოს და რომელი გადააგდოს ხელახლა; მეორე გდების შემდეგ შეიძლება ისევ გადააგდოს ნებისმიერი კამათელი (მათ შორის ადრე „შენახულებიც“). მესამე გდების შედეგი საბოლოოა.
2. მესამე გდების შემდეგ მოთამაშე ვალდებულია შედეგი **ერთ უჯრაში** ჩაწეროს ქულების ცხრილში. უკვე შევსებული უჯრა ხელახლა არ გამოიყენება — თუ არცერთი კომბინაცია არ ჯდება, ნებისმიერ თავისუფალ უჯრაში შეიძლება 0-ის ჩაწერა.
3. სტრატეგია და კამათლების შერჩევა შესაძლოა **კოლექტიურად** იქნას განხილული, მაგრამ საბოლოო გადაწყვეტილება ეკუთვნის იმ მოთამაშეს, ვინც კამათელს აგდებდა.

## ქულების ცხრილი
**ზედა ბლოკი** (ერთეულები–ექვსეულები): იწერება მოცემული რიცხვის კამათლების ჯამი. თუ ზედა ბლოკის ჯამმა მიაღწია **63-ს ან მეტს**, ემატება **35 ბონუს ქულა**.

**ქვედა ბლოკი:** წყვილი, ორი წყვილი, სამეული, ფული ჰაუსი (25), მცირე სტრიტი — 4 კამათელი რიგზე (30), დიდი სტრიტი — 5 კამათელი რიგზე (40), **იაძი** — ხუთივე ერთნაირი (50) და **შანსი** — ნებისმიერი კომბინაცია, კამათლების ჯამი, გამოსადეგი „გადამრჩენ“ უჯრად.

როგორც კი ცხრილის ყველა (**15**) სტრიქონი შეივსება, რაუნდი მთავრდება და ხდება ქულების დათვლა.

## გამარჯვება
თამაში მიმდინარეობს **3 რაუნდის** განმავლობაში. გამარჯვებისთვის საჭიროა სამივე რაუნდის ჯამში **777 ქულის** დაგროვება.

## ვარიანტები
- **მარტივი ვერსია:** მიზანი — 600 ქულა, 2 რაუნდი. ბავშვებთან და დამწყებთათვის.
- **ინდივიდუალურად:** ყველა თავისთვის, საკუთარი ცხრილით — ბოლოს ჯამი შედარდება (თანამშრომლობის გარეშე).
- **სპიდ-იაძი:** ერთი გდება სვლაზე, სამის ნაცვლად — 15 წუთში სრული თამაში.

## რჩევა
ერთ-ერთმა კამათელმა წიბოზე დაეცა და გუნდმა ხმაურიანად იკამათა, სამართლიანი იყო თუ არა მისი ხელახლა გდება — საბოლოოდ გადააგდებინეს, „ვინც ეჭვს არ ამორცხვენდა, სამართლიანობის გამო“. **წესი:** კამათელი, რომელიც წიბოზე ან საგანზე დაეყრდნო, ავტომატურად ხელახლა იგდება.`,
